def seed_behaviors(apps, schema_editor):
    SightingBehavior = apps.get_model("sightings", "SightingBehavior")
    for name, slug, sort_order in BEHAVIORS:
        SightingBehavior.objects.get_or_create(
            slug=slug,
            defaults={"name": name, "sort_order": sort_order},
        )

    # Retag photo-library sightings (marked in contribution.metadata.behaviour)
    # from the coarse legacy codes to their specific behaviour slug.
    MarineSighting = apps.get_model("sightings", "MarineSighting")
    valid = set(SightingBehavior.objects.values_list("slug", flat=True))
    for sighting in MarineSighting.objects.select_related("contribution").exclude(
        contribution__metadata__behaviour__isnull=True
    ):
        label = (sighting.contribution.metadata or {}).get("behaviour")
        if not label:
            continue
        target = slugify(str(label).replace("_", " ").replace("-", " "))
        if target in valid and sighting.behavior != target:
            sighting.behavior = target
            sighting.save(update_fields=["behavior"])


